namespace SilexGis.Domain.TestData;

/// <summary>How a table is filled when test data is generated.</summary>
public enum TestDataTableRole
{
    /// <summary>The generator writes its rows, through the ordinary write services.</summary>
    Generated,

    /// <summary>Filled as a consequence of generated rows: by a write service, a trigger or a job.</summary>
    Derived,

    /// <summary>To be generated by a part of the generator not built yet; the part is named.</summary>
    Planned,

    /// <summary>Deliberately never filled by the generator, for the stated reason.</summary>
    Exempt,
}

/// <param name="Part">For a planned or generated table, the part of the generator that writes it.</param>
public sealed record TestDataTableEntry(TestDataTableRole Role, string? Part, string Note);

/// <summary>The parts the generator is built in, each writing one area of the schema.</summary>
public static class TestDataParts
{
    public const string Geography = "geography";
    public const string People = "people";
    public const string Underground = "underground";
    public const string Activity = "activity";
    public const string Documents = "documents";
    public const string Geodata = "geodata";
    public const string Accounts = "accounts";

    public static IReadOnlyList<string> All { get; } = [Geography, People, Underground, Activity, Documents, Geodata, Accounts];

    /// <summary>The parts built so far; a table planned for one of them must be generated.</summary>
    public static IReadOnlySet<string> Built { get; } = new HashSet<string>(StringComparer.Ordinal) { Geography };
}

