    /// <summary>The tables the generator writes now: generated ones, and planned ones whose part is built.</summary>
    public static IEnumerable<string> GeneratedNow() =>
        All.Where(t => t.Value.Role == TestDataTableRole.Generated
                       || (t.Value.Role == TestDataTableRole.Planned && TestDataParts.Built.Contains(t.Value.Part!)))
            .Select(t => t.Key);
